// Computes the total effective skill-level bonus for a unit/skill pair from all bonus sources: shrine bonus, +all skills, +class skills, +skill-tab bonus (for same-class player), +non-class single-skill bonus (capped at 3), and +elemental-type skill bonus. Returns 0 if skill or record pointer is NULL or skill id is out of range. Result is added to the base nLevelBonus from the D2SkillStrc.
static int32_t __stdcall SKILL_GetLevelBonus(D2SkillStrc * pSkill, D2UnitStrc * pUnit) {
    int32_t nItemBonus;
    D2SkillDescTxt* pSkillDesc;
    int nStatBonus;
    if (!pSkill) {
      return 0;
    }

    D2SkillsTxt* pSkillsTxt;
    pSkillsTxt = pSkill->pRecord;
    if (!pSkillsTxt) {
      return 0;
    }

    uint16_t nSkillLayer;
    nSkillLayer = pSkillsTxt->skill;
    eD2Skills eSkillId;
    eSkillId = (eD2Skills)(short int)nSkillLayer;
    if ((int)eSkillId < 0 || (int)eSkillId >= sgptDataTable->nTxtSkillsCount) {
      return 0;
    }

    int nSkillStatVal;
    nSkillStatVal = pSkill->nLevelBonus;
    int32_t nShrineBonus;
    nShrineBonus = GetShrineBonus(pUnit);
    int32_t nTotalBonus;
    nTotalBonus = Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_item_allskills, 0);
    nSkillStatVal = nSkillStatVal + nShrineBonus + nTotalBonus;
    if (!pUnit || pUnit->eUnitType != UNIT_PLAYER) {
      if (pSkill->nLevel <= 0) {
        nStatBonus = Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_item_nonclassskill, nSkillLayer);
      } else {
        nStatBonus = Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_item_nonclassskill, nSkillLayer);
        if (!nStatBonus) {
          goto add_elem_and_single_bonus;
        }
        if (nStatBonus > 3) {
          nStatBonus = 3;
        }
      }
    } else if ((int)pSkillsTxt->charclass == pUnit->nClassId) {
      nItemBonus = Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_item_addclassskills, (uint16_t)pUnit->nClassId);
      nSkillStatVal += nItemBonus;
      pSkillDesc = D2Client::DataTbls::GetSkillDescription(eSkillId);
      if (pSkillDesc->skillpage != '\0') {
        nStatBonus = Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_item_addskill_tab, pSkillDesc->skillpage - 1 + (short int)pUnit->nClassId * 8);
        nSkillStatVal += nStatBonus;
      }

      nStatBonus = Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_item_nonclassskill, nSkillLayer);
      if (nStatBonus > 3) {
        nStatBonus = 3;
      }
    } else {
      nStatBonus = Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_item_nonclassskill, nSkillLayer);
    }

    nSkillStatVal += nStatBonus;
    add_elem_and_single_bonus:
    if (pSkillsTxt->EType != ELEMENTAL_NONE) {
      nStatBonus = Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_item_elemskill, (uint16_t)pSkillsTxt->EType);
      nSkillStatVal += nStatBonus;
    }
    nStatBonus = Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_item_singleskill, nSkillLayer);
    return nStatBonus + nSkillStatVal;
}

// Returns the effective level of a skill, optionally including level bonuses. Clamps result between 0 and max experience table level.
int __stdcall GetSkillLevel(D2UnitStrc * pUnit, D2SkillStrc * pSkill, BOOL bApplyBonus) {
    int32_t nLevelBonus;
    if (!pUnit || !pSkill) {
      return 0;
    }

    uint32_t nLevel = pSkill->nLevel;
    if (bApplyBonus && pSkill->nOwnerGUID == -1) {
      nLevelBonus = SKILL_GetLevelBonus(pSkill, pUnit);
      nLevel += nLevelBonus;
    }

    nLevel = (int)nLevel <= 0 ? 0 : nLevel;
    nLevelBonus = DATATBLS::DataTbls::TXT_Experience_GetMaxLevel(0);
    if ((int)nLevel < nLevelBonus) {
      return nLevel;
    }

    nLevelBonus = DATATBLS::DataTbls::TXT_Experience_GetMaxLevel(0);
    return nLevelBonus;
}

int32_t __stdcall GetSkillBonus(D2UnitStrc * pUnit, eD2Skills eSkill) {
    if (!pUnit) {
      return 0;
    }

    D2SkillStrc* pSkill = GetSkillByIdAndOwner(pUnit, eSkill, -1);
    if (pSkill && pSkill->nOwnerGUID == -1) {
      int32_t nBonus;
      nBonus = SKILL_GetLevelBonus(pSkill, pUnit);
      return nBonus;
    }

    return 0;
}

