static int32_t UNIT_GetSkillBySkillId(D2SkillsTxt * pSkillsTxt, D2UnitStrc * pUnit) {
    D2SkillStrc* pSkillIter = Units::GetFirstSkill(pUnit);
    if (!pSkillIter) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0xab0);
      exit(-1);
    }

    do {
      if (pSkillIter->pRecord == pSkillsTxt) {
        return 1;
      }

      pSkillIter = pSkillIter->pNext;
    } while (pSkillIter);

    return 0;
}

int32_t __stdcall TXT_Skills_GetReqLevel(eD2Skills eSkill) {
    D2SkillsTxt* pSkillsTxt = (int)eSkill >= 0 && (int)eSkill < sgptDataTable->nTxtSkillsCount ? sgptDataTable->pTxtSkills + eSkill : nullptr;
    if (!pSkillsTxt) {
      return 0x7fffffff;
    }

    return (int)pSkillsTxt->reqlevel;
}

int32_t __stdcall SKILL_GetRequiredLevel(D2UnitStrc * pUnit, eD2Skills eSkill) {
    D2SkillsTxt* pSkillsTxt = (int)eSkill >= 0 && (int)eSkill < sgptDataTable->nTxtSkillsCount ? sgptDataTable->pTxtSkills + eSkill : nullptr;
    if (!pSkillsTxt) {
      return 0x7fffffff;
    }

    int32_t nReqLevel = (int32_t)pSkillsTxt->reqlevel;
    D2SkillStrc* pSkill = GetSkillByIdAndOwner(pUnit, eSkill, -1);
    if (!pSkill) {
      return nReqLevel;
    }

    nReqLevel += pSkill->nLevel;
    return nReqLevel;
}

